{"path":"src/services/formatter.ts","contents":"// src/services/formatter.ts
//
// Formatter service. Returns results, never throws — callers branch on success.

export interface FormatterOptions {
  timeoutMs: number;
  retries: number;
  verbose: boolean;
}

export const DEFAULT_FORMATTER_OPTIONS: FormatterOptions = {
  timeoutMs: 5000,
  retries: 3,
  verbose: false,
};

export async function runFormatter(
  input: string,
  options: FormatterOptions = DEFAULT_FORMATTER_OPTIONS,
): Promise<{ success: boolean; value?: string; error?: string }> {
  if (!input) {
    return { success: false, error: "formatter: empty input" };
  }
  if (options.verbose) {
    console.log(`formatter: processing ${input.length} chars`);
  }
  return { success: true, value: input.trim() };
}
"}

